/* Procedure structure for procedure `SALVARLOCALIZACAO` */

/*!50003 DROP PROCEDURE IF EXISTS  `SALVARLOCALIZACAO` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`%` PROCEDURE `SALVARLOCALIZACAO`(IN USU INT, IN LATIT DOUBLE, IN LONGIT DOUBLE, IN DH DATETIME,
IN VELATUI FLOAT,IN ALTITUDEI FLOAT,IN ORIENTI VARCHAR(3))
BEGIN
    INSERT INTO LOCALIZACAO (USUCOD,DATAHORA,VELATU,ALTITUDE,ORIENT,LOCLATLONG)
    VALUES (USU,DH,VELATUI,ALTITUDEI,ORIENTI,POINT(LONGIT,LATIT));
   
    SELECT ROW_COUNT();
    END */$$
DELIMITER ;

